281	<script>
282	import router from '@system.router'
283	import storage from '@system.storage'
284	import velaclaw from '@system.velaclaw'
285	
286	export default {
287	  data: {
288	    rideTime: '00:00:00',
289	    currentSpeed: '0.0',
290	    totalDistance: '0.0',
291	    avgSpeed: '0.0',
292	    calories: '0',
293	    statusText: '骑行中',
294	    statusClass: 'riding',
295	    isPaused: false,
296	    motionIcon: '🚶',
297	    motionText: '静止',
298	    progressPercent: 0,
299	    timeToRest: 60,
300	    showAlert: false,
301	    alertMessage: '',
302	    rideStartTime: null,
303	    rideSeconds: 0,
304	    timer: null
305	  },
306	
307	  onInit() {
308	    this.startRide()
309	  },
310	
311	  onDestroy() {
312	    if (this.timer) {
313	      clearInterval(this.timer)
314	    }
315	  },
316	
317	  startRide() {
318	    this.rideStartTime = Date.now()
319	    this.timer = setInterval(() => {
320	      if (!this.isPaused) {
321	        this.rideSeconds++
322	        this.updateRideTime()
323	        this.checkRestReminder()
324	      }
325	    }, 1000)
326	  },
327	
328	  updateRideTime() {
329	    const hours = Math.floor(this.rideSeconds / 3600)
330	    const minutes = Math.floor((this.rideSeconds % 3600) / 60)
331	    const seconds = this.rideSeconds % 60
332	    this.rideTime = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
333	  },
334	
335	  checkRestReminder() {
336	    const minutesRiding = Math.floor(this.rideSeconds / 60)
337	    this.progressPercent = Math.min((minutesRiding / 60) * 100, 100)
338	    this.timeToRest = Math.max(60 - minutesRiding, 0)
339	
340	    if (minutesRiding > 0 && minutesRiding % 45 === 0) {
341	      this.showSafetyAlert('已连续骑行45分钟，建议休息一下')
342	    }
343	  },
344	
345	  togglePause() {
346	    this.isPaused = !this.isPaused
347	    this.statusText = this.isPaused ? '已暂停' : '骑行中'
348	    this.statusClass = this.isPaused ? 'paused' : 'riding'
349	  },
350	
351	  async stopRide() {
352	    if (this.timer) {
353	      clearInterval(this.timer)
354	    }
355	
356	    // 保存骑行记录
357	    await this.saveRideRecord()
358	
359	    // 生成 AI 复盘
360	    try {
361	      const result = await velaclaw.ask({
362	        query: `我刚完成一次骑行，时长${this.rideTime}，距离${this.totalDistance}公里，请给我一个简短的骑行复盘和建议`
363	      })
364	      console.log('AI Review:', result.reply)
365	      // TODO: 跳转到复盘页面显示结果
366	    } catch (err) {
367	      console.error('AI Review Error:', err)
368	    }
369	
370	    router.back()
371	  },
372	
373	  async saveRideRecord() {
374	    const record = {
375	      startTime: this.rideStartTime,
376	      endTime: Date.now(),
377	      duration: this.rideSeconds,
378	      distance: parseFloat(this.totalDistance),
379	      avgSpeed: parseFloat(this.avgSpeed),
380	      calories: parseInt(this.calories)
381	    }
382	
383	    try {
384	      await storage.get({
385	        key: 'rideHistory',
386	        success: (data) => {
387	          const history = JSON.parse(data || '[]')
388	          history.push(record)
389	          storage.set({
390	            key: 'rideHistory',
391	            value: JSON.stringify(history)
392	          })
393	        },
394	        fail: () => {
395	          storage.set({
396	            key: 'rideHistory',
397	            value: JSON.stringify([record])
398	          })
399	        }
400	      })
401	    } catch (err) {
402	      console.error('Save record error:', err)
403	    }
404	  },
405	
406	  showSafetyAlert(message) {
407	    this.showAlert = true
408	    this.alertMessage = message
409	    setTimeout(() => {
410	      this.showAlert = false
411	    }, 5000)
412	  }
413	}
414	</script>
